( . "$PREFIX/etc/profile.d/start-services.sh" 2>/dev/null || true; i=0; while [ "$i" -lt 25 ] && ! pgrep -f runsvdir >/dev/null 2>&1; do sleep 0.2; i=$((i+1)); done; sv-enable sshd >/dev/null 2>&1 || true; i=0; while [ "$i" -lt 25 ]; do sv status sshd 2>/dev/null | grep -q '^run:' && break; sv up sshd >/dev/null 2>&1 || true; sleep 0.2; i=$((i+1)); done; pgrep -x sshd >/dev/null 2>&1 || sshd -p {{port}})
